import { useRecoilValue, useSetRecoilState } from "recoil";
import { categoriesState, selectedCategoryState } from "../atoms/categoryAtom";
import { todoListState } from "../atoms/todoAtom";
import { useForm } from "react-hook-form";
import styled from "styled-components";

interface IForm {
	toDo: string;
}

const Form = styled.form`
	display: flex;
`;

const Input = styled.input`
	width: max-content;
	height: 40px;
	/* padding: 8px 20px; */
	border: 1px solid #000;
	border-radius: 8px;
`;

const AddButton = styled.button`
	display: inline-flex;
	width: auto;
	white-space: nowrap;
	text-align: center;
	font-size: 14px;
	font-weight: 500;
	padding: 8px 16px;
	border-radius: 8px; 
	background-color: ${(props) => props.theme.bgColors.dimmed};
	color: ${ (props) => props.theme.textColors.normal };
	box-shadow: 0px 2px 4px rgba(0, 0, 0, 0.2);
`;

function CreateToDo() {
	const setToDoList = useSetRecoilState(todoListState);
	const category = useRecoilValue(selectedCategoryState);
	const categories = useRecoilValue(categoriesState);

	const { register, handleSubmit, setValue } = useForm<IForm>();
	const handleValid = ({ toDo }: IForm) => {
    setToDoList((oldToDos) => [
      { id: Date.now(), text: toDo, category: category ?? categories[0]},
      ...oldToDos,
    ]);
    setValue("toDo", "");
  };

	return (
		<form 
			onSubmit={handleSubmit(handleValid)}
			style={{backgroundColor: "#000"}}
		>
			<Input {...register(
					"toDo",
					{ required: "Please write a to do." },
				)}
				placeholder="wirte a to do"
			></Input>
			<AddButton>add</AddButton>
		</form>
	);
}

export default CreateToDo;
